      if (f.length < 3) return
      const dir = f[0].trim(), type = (f[1] || '文字').trim() || '文字', text = f.slice(2).join('|').trim()
      if (!dir || !text) return
      if (putBoth(owner, contact, { dir, type, text, time })) changed = true
    })
  })
